CREATE TABLE public.staff_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, business_id uuid NOT NULL REFERENCES public.businesses(id), branch_id uuid REFERENCES public.business_branches(id), author_id uuid NOT NULL DEFAULT auth.uid(), title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 160), body text NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 12000), kind text NOT NULL DEFAULT 'note' CHECK(kind IN ('note','report')), status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','approved','returned')), feedback text NOT NULL DEFAULT '', reviewed_by uuid, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.staff_reports TO authenticated; GRANT ALL ON public.staff_reports TO service_role;
ALTER TABLE public.staff_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY reports_read ON public.staff_reports FOR SELECT TO authenticated USING (auth.uid()=owner_id OR public.has_role(auth.uid(),'super_admin') OR (author_id=auth.uid() AND public.assistant_can(owner_id,'notes_view') AND public.can_access_branch_data(owner_id,business_id,branch_id)));
CREATE POLICY reports_create ON public.staff_reports FOR INSERT TO authenticated WITH CHECK (author_id=auth.uid() AND public.assistant_can(owner_id,'notes_create') AND public.can_access_branch_data(owner_id,business_id,branch_id) AND EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=business_id AND b.created_by=owner_id) AND status='submitted' AND feedback='' AND reviewed_by IS NULL AND reviewed_at IS NULL);
CREATE POLICY reports_update ON public.staff_reports FOR UPDATE TO authenticated USING (auth.uid()=owner_id OR public.has_role(auth.uid(),'super_admin') OR (author_id=auth.uid() AND status='returned' AND public.assistant_can(owner_id,'notes_create') AND public.can_access_branch_data(owner_id,business_id,branch_id))) WITH CHECK (auth.uid()=owner_id OR public.has_role(auth.uid(),'super_admin') OR (author_id=auth.uid() AND status='submitted' AND public.assistant_can(owner_id,'notes_create') AND public.can_access_branch_data(owner_id,business_id,branch_id)));
CREATE POLICY reports_delete ON public.staff_reports FOR DELETE TO authenticated USING (auth.uid()=owner_id OR public.has_role(auth.uid(),'super_admin'));
CREATE FUNCTION public.guard_staff_report() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.owner_id IS DISTINCT FROM OLD.owner_id OR NEW.business_id IS DISTINCT FROM OLD.business_id OR NEW.branch_id IS DISTINCT FROM OLD.branch_id OR NEW.author_id IS DISTINCT FROM OLD.author_id OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'Huwezi kubadili mmiliki wa taarifa' USING ERRCODE='42501'; END IF; IF auth.uid()=OLD.owner_id OR public.has_role(auth.uid(),'super_admin') THEN IF NEW.status NOT IN ('approved','returned') THEN RAISE EXCEPTION 'Chagua kukubali au kurudisha'; END IF; NEW.reviewed_by:=auth.uid(); NEW.reviewed_at:=now(); ELSE IF OLD.status<>'returned' OR NEW.status<>'submitted' OR NEW.feedback IS DISTINCT FROM OLD.feedback OR NEW.reviewed_by IS DISTINCT FROM OLD.reviewed_by OR NEW.reviewed_at IS DISTINCT FROM OLD.reviewed_at THEN RAISE EXCEPTION 'Huna ruhusa ya kuthibitisha taarifa' USING ERRCODE='42501'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_staff_report BEFORE UPDATE ON public.staff_reports FOR EACH ROW EXECUTE FUNCTION public.guard_staff_report();
CREATE INDEX staff_reports_scope ON public.staff_reports(business_id,created_at DESC);
CREATE TABLE public.platform_announcements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 160), summary text NOT NULL CHECK(length(trim(summary)) BETWEEN 1 AND 12000), kind text NOT NULL DEFAULT 'announcement' CHECK(kind IN ('announcement','release')), version text, is_active boolean NOT NULL DEFAULT true, created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.platform_announcements TO authenticated; GRANT ALL ON public.platform_announcements TO service_role;
ALTER TABLE public.platform_announcements ENABLE ROW LEVEL SECURITY;
CREATE POLICY announcement_read ON public.platform_announcements FOR SELECT TO authenticated USING (is_active OR public.has_role(auth.uid(),'super_admin'));
CREATE POLICY announcement_admin ON public.platform_announcements FOR ALL TO authenticated USING(public.has_role(auth.uid(),'super_admin')) WITH CHECK(public.has_role(auth.uid(),'super_admin'));
CREATE TABLE public.release_preferences (user_id uuid NOT NULL DEFAULT auth.uid(), announcement_id uuid NOT NULL REFERENCES public.platform_announcements(id) ON DELETE CASCADE, choice text NOT NULL CHECK(choice IN ('accepted','later','read')), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,announcement_id));
GRANT SELECT,INSERT,UPDATE ON public.release_preferences TO authenticated; GRANT ALL ON public.release_preferences TO service_role;
ALTER TABLE public.release_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_release_choice ON public.release_preferences FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.stock_order_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, business_id uuid NOT NULL REFERENCES public.businesses(id), branch_id uuid REFERENCES public.business_branches(id), product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, trigger_threshold numeric NOT NULL CHECK(trigger_threshold>=0), order_quantity numeric NOT NULL CHECK(order_quantity>0), supplier_info text NOT NULL DEFAULT '', is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.stock_order_rules TO authenticated; GRANT ALL ON public.stock_order_rules TO service_role;
ALTER TABLE public.stock_order_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY stock_rules_access ON public.stock_order_rules FOR ALL TO authenticated USING(public.can_access_branch_data(owner_id,business_id,branch_id) AND public.assistant_can(owner_id,'inventory_automation')) WITH CHECK(public.can_access_branch_data(owner_id,business_id,branch_id) AND public.assistant_can(owner_id,'inventory_automation') AND EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND p.owner_id=stock_order_rules.owner_id AND p.business_id=stock_order_rules.business_id AND p.branch_id IS NOT DISTINCT FROM stock_order_rules.branch_id));
CREATE POLICY suppliers_catalog_required ON public.suppliers AS RESTRICTIVE FOR ALL TO authenticated USING(public.assistant_can(owner_id,'suppliers_manage') AND public.can_access_branch_data(owner_id,NULL,NULL)) WITH CHECK(public.assistant_can(owner_id,'suppliers_manage') AND public.can_access_branch_data(owner_id,NULL,NULL));
CREATE POLICY purchases_catalog_required ON public.purchase_orders AS RESTRICTIVE FOR ALL TO authenticated USING(public.assistant_can(owner_id,'suppliers_manage') AND public.can_access_branch_data(owner_id,NULL,NULL)) WITH CHECK(public.assistant_can(owner_id,'suppliers_manage') AND public.can_access_branch_data(owner_id,NULL,NULL));
CREATE POLICY snapshots_read_required ON public.inventory_snapshots AS RESTRICTIVE FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND p.owner_id=inventory_snapshots.owner_id AND public.can_access_branch_data(p.owner_id,p.business_id,p.branch_id) AND public.assistant_can(p.owner_id,'can_view_inventory')));
CREATE POLICY snapshots_write_required ON public.inventory_snapshots AS RESTRICTIVE FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND p.owner_id=inventory_snapshots.owner_id AND public.can_access_branch_data(p.owner_id,p.business_id,p.branch_id) AND public.assistant_can(p.owner_id,'can_view_inventory'))) WITH CHECK(EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND p.owner_id=inventory_snapshots.owner_id AND public.can_access_branch_data(p.owner_id,p.business_id,p.branch_id) AND public.assistant_can(p.owner_id,'inventory_snapshot_create')));
CREATE POLICY snapshots_modify_required ON public.inventory_snapshots AS RESTRICTIVE FOR DELETE TO authenticated USING(public.assistant_can(owner_id,'inventory_snapshot_create'));
ALTER PUBLICATION supabase_realtime ADD TABLE public.staff_reports, public.platform_announcements, public.stock_order_rules;
